## **🛠️ НУЖНЫЕ ДОРАБОТКИ main.py:**

### **1. Добавить отдельный endpoint для delete_file (опционально)**
```python
@app.post("/api/delete")
async def delete_file_endpoint(data: dict):
    """
    Прямое удаление файла через API
    {
      "path": "honeycombs/registry/extensions/visualizations.json",
      "message": "Удаление дублирующегося файла"
    }
    """
    if not GITHUB_TOKEN:
        return {"error": "GitHub токен не настроен"}

    path = data.get("path")
    if not path:
        return {"error": "Не указан путь к файлу"}

    # Используем существующую логику из handle_apply_patch
    async with httpx.AsyncClient() as client:
        headers = {"Authorization": f"token {GITHUB_TOKEN}"}
        url = f"https://api.github.com/repos/{GITHUB_REPO}/contents/{path}"

        # Получаем SHA файла
        resp = await client.get(url, headers=headers)
        if resp.status_code == 404:
            return {"error": "Файл не найден"}
        if resp.status_code != 200:
            return {"error": f"Ошибка доступа: {resp.status_code}"}

        file_sha = resp.json().get("sha")
        commit_msg = data.get("message", f"🗑️ Удалён {path}")

        del_resp = await client.delete(url, headers=headers, json={
            "message": commit_msg,
            "sha": file_sha,
            "branch": "main"
        })

        if del_resp.status_code == 200:
            return {"success": True, "message": "Файл удалён"}
        else:
            return {"error": f"GitHub DELETE: {del_resp.status_code}"}
```

### **2. WebSocket команда для удаления**
```python
# Добавить в websocket_endpoint
elif msg_type == "delete_file":
    await handle_delete_file(message, websocket)

async def handle_delete_file(message: dict, websocket: WebSocket):
    session_id = message.get("session_id", "unknown")
    path = message.get("path", "")
    if not path:
        await manager.send_to(websocket, {"type": "error", "text": "❌ Не указан путь к файлу"})
        return

    # Используем существующую логику удаления
    patch_data = {
        "file_path": path,
        "delete_file": true
    }

    await handle_apply_patch({
        "session_id": session_id,
        "patch": patch_data
    }, websocket)
```

